// Generated from assets/*.svg by gen-brand-art.py — do not edit by hand.
//
// Why a data module instead of react-native-svg-transformer: the transformer
// needs a metro.config.js, and this project deliberately has none, so the
// default Expo setup stays intact and no SVG import can break a build. The
// tradeoff is that the geometry is copied rather than imported, which is why it
// is transcribed by a script and checked by re-rendering — see
// docs/phase-6-brand-assets.md.
//
// The three native icons (app-icon, splash-icon, favicon) are absent on
// purpose: Expo's app config takes rasters, so gen-icons.py renders them to PNG
// instead.
//
// `TEXT` nodes are rendered with the device font. Only onboarding-03 ("Rp" on a
// coin) and primary-logo (the "Kitasaku" wordmark) contain any, and the design's
// Arial is not on-device on every platform.

export type BrandNode =
  | { t: 'path'; d: string; fill?: string; stroke?: string; sw?: number; cap?: string; join?: string; transform?: string }
  | { t: 'circle'; cx: number; cy: number; r: number; fill?: string; stroke?: string; sw?: number; transform?: string }
  | { t: 'rect'; x: number; y: number; w: number; h: number; rx?: number; fill?: string; stroke?: string; sw?: number; transform?: string }
  | { t: 'ellipse'; cx: number; cy: number; rx: number; ry: number; fill?: string; stroke?: string; sw?: number; transform?: string }
  | { t: 'g'; children: BrandNode[]; transform?: string }
  | { t: 'text'; x: number; y: number; content: string; size: number; fill: string; anchor?: string };

export interface BrandArt {
  /** The <title> from the SVG, used as the accessibility label. */
  title: string;
  /** 512x512 for every icon in the pack. */
  viewBox: number;
  nodes: BrandNode[];
}

